arguments.content:
import math
import random
from cluster_analysis import nodes, N, T_mat, E_mat, D_mat, regions
from tour_search2 import eval_tour

id_to_idx = {nodes[i]["id"]: i for i in range(N)}
all_targets = list(range(1, N))

# Let's check if we can beat 56.75 by running a large-scale genetic / memetic algorithm + variable neighborhood search!
def local_improve(seq, max_return_tick=400):
    cur = list(seq)
    cur_sc, cur_et, _ = eval_tour(cur, max_return_tick=max_return_tick)
    improved = True
    while improved:
        improved = False
        # 1. Try 2-opt
        for i in range(len(cur)):
            for j in range(i + 1, len(cur)):
                cand = cur[:i] + list(reversed(cur[i:j+1])) + cur[j+1:]
                sc, et, _ = eval_tour(cand, max_return_tick=max_return_tick)
                if sc > cur_sc + 1e-6 or (abs(sc - cur_sc) <= 1e-6 and et < cur_et - 1e-4):
                    cur, cur_sc, cur_et = cand, sc, et
                    improved = True
                    break
            if improved:
                break
        if improved:
            continue
        # 2. Try single target relocate
        for i in range(len(cur)):
            x = cur[i]
            rem = cur[:i] + cur[i+1:]
            for j in range(len(rem) + 1):
                if j == i:
                    continue
                cand = rem[:j] + [x] + rem[j:]
                sc, et, _ = eval_tour(cand, max_return_tick=max_return_tick)
                if sc > cur_sc + 1e-6 or (abs(sc - cur_sc) <= 1e-6 and et < cur_et - 1e-4):
                    cur, cur_sc, cur_et = cand, sc, et
                    improved = True
                    break
            if improved:
                break
        if improved:
            continue
        # 3. Try inserting an unvisited target
        in_set = set(cur)
        for x in all_targets:
            if x in in_set:
                continue
            for j in range(len(cur) + 1):
                cand = cur[:j] + [x] + cur[j:]
                sc, et, _ = eval_tour(cand, max_return_tick=max_return_tick)
                if sc > cur_sc + 1e-6 or (abs(sc - cur_sc) <= 1e-6 and et < cur_et - 1e-4):
                    cur, cur_sc, cur_et = cand, sc, et
                    improved = True
                    break
            if improved:
                break
        if improved:
            continue
        # 4. Try replacing a visited target with an unvisited one at any position
        for i in range(len(cur)):
            rem = cur[:i] + cur[i+1:]
            for x in all_targets:
                if x in in_set:
                    continue
                for j in range(len(rem) + 1):
                    cand = rem[:j] + [x] + rem[j:]
                    sc, et, _ = eval_tour(cand, max_return_tick=max_return_tick)
                    if sc > cur_sc + 1e-6 or (abs(sc - cur_sc) <= 1e-6 and et < cur_et - 1e-4):
                        cur, cur_sc, cur_et = cand, sc, et
                        improved = True
                        break
                if improved:
                    break
            if improved:
                break
    return cur_sc, cur_et, cur

# Test various hand-crafted macro-routes and random perturbations
r_map = {
    "NB": regions["NEAR_BASE (x=260..400, y=200..355)"],
    "NE": regions["NORTH_EAST (x=510..580, y=150..375)"],
    "SE": regions["SOUTH_EAST (x=310..500, y=30..160)"],
    "NW": regions["NORTH_WEST (x=60..170, y=220..375)"],
    "SW": regions["SOUTH_WEST (x=20..260, y=20..110)"],
}

macro_orders = [
    ["NB", "SE", "SW"],
    ["SE", "SW", "NB"],
    ["NW", "SW", "SE", "NB"],
    ["NW", "NB", "SE"],
    ["NE", "SE", "NB"],
    ["NE", "NB", "SW"],
    ["NB", "NE", "SE"],
]

best_overall = (-1.0, 999.0, [])
random.seed(99)

for mo in macro_orders:
    # Build a feasible seed from macro order
    seed = []
    for rname in mo:
        # sort by deadline
        sub = sorted(r_map[rname], key=lambda k: (nodes[k]["deadline_tick"] or 999, -nodes[k]["value"]))
        for x in sub:
            if eval_tour(seed + [x])[0] > 0:
                seed.append(x)
    sc, et, s = local_improve(seed)
    print(f"Macro {mo}: score={sc:.2f}, end_tick={et:.1f}, len={len(s)}")
    if sc > best_overall[0] or (sc == best_overall[0] and et < best_overall[1]):
        best_overall = (sc, et, s)

    # Now do 40 Iterated Local Search kicks from s
    cur_s = list(s)
    cur_sc, cur_et = sc, et
    for kick in range(40):
        cand = list(cur_s)
        # drop 2-5 random targets
        for _ in range(random.randint(2, min(5, max(2, len(cand))))):
            cand.pop(random.randrange(len(cand)))
        # shuffle a subsegment
        if len(cand) >= 4:
            i = random.randint(0, len(cand) - 3)
            sub = cand[i:i+3]
            random.shuffle(sub)
            cand[i:i+3] = sub
        sc2, et2, s2 = local_improve(cand)
        if sc2 > cur_sc or (sc2 == cur_sc and et2 < cur_et) or random.random() < 0.15:
            cur_s, cur_sc, cur_et = s2, sc2, et2
        if sc2 > best_overall[0] or (sc2 == best_overall[0] and et2 < best_overall[1]):
            best_overall = (sc2, et2, s2)
            print(f"  [ILS {mo}] New overall best: score={sc2:.2f}, end_tick={et2:.1f}, len={len(s2)}")

sc, et, det = eval_tour(best_overall[2])
print(f"\n=== FINAL BEST TOUR (max_return_tick=400): Score={sc:.2f} / 98.0, end_tick={et:.1f}, count={len(best_overall[2])} ===")
for tid, st, dl, val, full_val in det:
    idx = id_to_idx[tid]
    t = nodes[idx]
    status = "ON-TIME" if val == full_val else "LATE"
    print(f"  {tid:4s} ({t['x']:5.1f},{t['y']:5.1f}) tick={st:3d} dl={str(dl):4s} earned={val:4.2f}/{full_val:3.1f} [{status}]")

